#!/usr/bin/env node
'use strict';
// Preparation only: execution requires an explicitly supplied accepted HEAD.
// This wrapper neither installs dependencies nor starts a browser/server.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const os = require('node:os');
const { spawn, spawnSync } = require('node:child_process');
const { pathToFileURL } = require('node:url');
const { createRequire } = require('node:module');
const { performance } = require('node:perf_hooks');

const HISTORY = 'spec/process/evidence/health-audit-20261107';
const MANIFEST_SHA = 'd6346a4afe203568d0238455a425cbe042fc43351a1d07a632114812bfdbc426';
const ARCHIVER_SHA = 'cece38c0d93c54852f4c0aaa32c1a6004dbcca308117c54dcce8c84d5289dbdc';
const CHECKER_SHA = '3c53f53f105c7edf6b57669ce61680707670624160d1b41b3e63af86b89fef23';
const TOOLS = {
  'performance-runner.mjs': '53224b6ec0fcfb835650890fdea12e2a5216182c4288047ea5a7960e025e2add',
  'performance-worker.mjs': '44bf82d8151885ee3d8fcb700562837e0a1075327a2fc6a888c1cdb39ac08254',
  'performance-fixtures.mjs': '3d16d60df721021fe803493ad2f4e3da4eb007286fd0a0374698a60a9eb83967',
  'performance-common.mjs': '8870a27525937d03fd4f1bad79ca7869d2b4ad27985988e9b6e40e5bf0c49ba9',
  'dependency-classifier.mjs': '9b8f10b02a82d90086f6ee2378d2b57b714d09631e6c6bd6bb58e0068c8806fe',
};
const hash = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const hashFile = file => hash(fs.readFileSync(file));
const key = file => process.platform === 'win32' ? path.resolve(file).toLowerCase() : path.resolve(file);
const errorData = error => ({ name: error?.name ?? 'Error', message: error?.message ?? String(error), stack: error?.stack ?? null });
const readJson = file => JSON.parse(fs.readFileSync(file, 'utf8'));
const jsonBytes = value => Buffer.from(JSON.stringify(value, null, 2) + '\n');
function argsOf(argv) {
  const result = {};
  for (let index = 0; index < argv.length; index += 2) {
    const name = argv[index], value = argv[index + 1];
    assert.ok(['--repo', '--expected-head', '--out'].includes(name), 'Unknown argument: ' + name);
    assert.ok(!Object.hasOwn(result, name) && value && !value.startsWith('--'), 'Duplicate or missing argument: ' + name);
    result[name] = value;
  }
  for (const name of ['--repo', '--expected-head', '--out']) assert.ok(result[name], 'Required ' + name);
  assert.match(result['--expected-head'], /^[0-9a-f]{40}$/, 'Expected an exact lowercase 40-character SHA');
  return result;
}
function git(repo, ...args) {
  const result = spawnSync('git', ['-C', repo, ...args], { encoding: 'utf8', windowsHide: true, timeout: 30000, maxBuffer: 16 * 1024 * 1024 });
  assert.equal(result.status, 0, 'git ' + args.join(' ') + ': ' + (result.stderr || result.error?.message));
  return result.stdout;
}
function inside(root, target) {
  const relative = path.relative(root, target);
  return relative === '' || (!relative.startsWith('..' + path.sep) && relative !== '..' && !path.isAbsolute(relative));
}
function canonicalNew(target) {
  const resolved = path.resolve(target);
  assert.equal(fs.existsSync(resolved), false, 'Output must be fresh; no prior receipt may be overwritten');
  const parent = fs.realpathSync(path.dirname(resolved));
  return path.join(parent, path.basename(resolved));
}
function outsideGit(target) {
  for (let current = fs.existsSync(target) && fs.statSync(target).isDirectory() ? target : path.dirname(target); ; current = path.dirname(current)) {
    assert.equal(fs.existsSync(path.join(current, '.git')), false, 'External tool/evidence must not be inside a Git worktree: ' + target);
    if (path.dirname(current) === current) return;
  }
}
function regular(file) {
  const stat = fs.lstatSync(file);
  assert.ok(stat.isFile() && !stat.isSymbolicLink(), 'Expected a regular, unlinked file: ' + file);
  return { path: file, bytes: stat.size, sha256: hashFile(file) };
}
function fileSet(root) {
  const result = [];
  function visit(directory) {
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      assert.equal(entry.isSymbolicLink(), false, 'Symlink in evidence/tool inventory');
      const file = path.join(directory, entry.name);
      if (entry.isDirectory()) visit(file);
      else { assert.ok(entry.isFile()); result.push(path.relative(root, file).replaceAll('\\', '/')); }
    }
  }
  visit(root);
  return result.sort();
}
function ownedDependencies(repo) {
  const directory = path.join(repo, 'vendor/toubkal/node_modules');
  const stat = fs.lstatSync(directory);
  assert.ok(stat.isDirectory() && !stat.isSymbolicLink(), 'vendor node_modules must be a physical directory, not a junction/symlink');
  assert.equal(key(fs.realpathSync(directory)), key(directory), 'vendor node_modules resolves outside its owning worktree');
  const rootModules = path.join(repo, 'node_modules');
  if (fs.existsSync(rootModules)) {
    assert.ok(fs.lstatSync(rootModules).isDirectory() && !fs.lstatSync(rootModules).isSymbolicLink());
    assert.equal(key(fs.realpathSync(rootModules)), key(rootModules), 'Root node_modules is shared through a link');
  }
  const lock = readJson(path.join(repo, 'vendor/toubkal/package-lock.json'));
  const names = ['@salusoft89/planegcs', 'opencascade.js', 'tsx', 'esbuild', 'typescript', 'semver'];
  const packages = names.map(name => {
    const folder = path.join(directory, name);
    assert.equal(key(fs.realpathSync(folder)), key(folder), 'Installed package is redirected: ' + name);
    const info = regular(path.join(folder, 'package.json')), pkg = readJson(info.path);
    assert.equal(pkg.version, lock.packages['node_modules/' + name]?.version, 'Installed version does not match the accepted lock: ' + name);
    return { name, version: pkg.version, packageJsonSha256: info.sha256 };
  });
  return { directory, realPath: fs.realpathSync(directory), dev: stat.dev, ino: stat.ino, packages, hiddenLock: regular(path.join(directory, '.package-lock.json')) };
}
function encoded(bytes) {
  const utf8 = bytes.toString('utf8');
  return { bytes: bytes.length, sha256: hash(bytes), encoding: Buffer.from(utf8).equals(bytes) ? 'utf8' : 'base64', data: Buffer.from(utf8).equals(bytes) ? utf8 : bytes.toString('base64') };
}
async function execute(command, argv, options) {
  const started = performance.now(), stdout = [], stderr = [];
  let child, timer, cleanupTimer, settled = false, outputBytes = 0;
  let timedOut = false, outputLimit = false, interrupted = false, spawnError = null;
  const cleanup = [];
  return await new Promise(resolve => {
    const onInterrupt = () => { interrupted = true; stopOwned('WRAPPER_INTERRUPTED'); };
    function finish(exitCode, signal, closed) {
      if (settled) return;
      settled = true;
      clearTimeout(timer); clearTimeout(cleanupTimer);
      process.off('SIGINT', onInterrupt); process.off('SIGTERM', onInterrupt);
      if (!closed) { child.stdout.destroy(); child.stderr.destroy(); child.unref(); }
      resolve({ pid: child.pid ?? null, exitCode, signal, elapsedMs: performance.now() - started, timeoutMs: options.timeoutMs,
        timedOut, outputLimit, interrupted, spawnError, closed, cleanup, stdout: Buffer.concat(stdout), stderr: Buffer.concat(stderr) });
    }
    function stopOwned(reason) {
      if (!child?.pid || settled || cleanup.length) return;
      if (child.exitCode !== null || child.signalCode !== null) {
        cleanup.push({ reason, action: 'Process exited; waiting for owned output pipes to close' });
      } else if (process.platform === 'win32') {
        const taskkill = path.join(process.env.SystemRoot || 'C:\\Windows', 'System32/taskkill.exe');
        const stop = spawnSync(taskkill, ['/PID', String(child.pid), '/T', '/F'], { encoding: 'utf8', windowsHide: true, timeout: 15000, maxBuffer: 1024 * 1024 });
        cleanup.push({ reason, command: [taskkill, '/PID', String(child.pid), '/T', '/F'], exitCode: stop.status,
          stdout: stop.stdout ?? '', stderr: stop.stderr ?? '', error: stop.error ? errorData(stop.error) : null });
      } else {
        try { process.kill(-child.pid, 'SIGKILL'); cleanup.push({ reason, ownedProcessGroup: child.pid, signal: 'SIGKILL', error: null }); }
        catch (error) { cleanup.push({ reason, ownedProcessGroup: child.pid, error: errorData(error) }); }
      }
      cleanupTimer = setTimeout(() => {
        try { child.kill('SIGKILL'); } catch (error) { cleanup.push({ reason: 'Owned handle fallback', error: errorData(error) }); }
        finish(child.exitCode, child.signalCode, false);
      }, 10000);
    }
    child = spawn(command, argv, { cwd: options.cwd, env: options.env, windowsHide: true, detached: process.platform !== 'win32', stdio: ['ignore', 'pipe', 'pipe'] });
    for (const [stream, chunks] of [[child.stdout, stdout], [child.stderr, stderr]]) stream.on('data', bytes => {
      chunks.push(bytes); outputBytes += bytes.length;
      if (outputBytes > 32 * 1024 * 1024 && !outputLimit) { outputLimit = true; stopOwned('OUTPUT_BUDGET_EXCEEDED'); }
    });
    child.on('error', error => { spawnError = errorData(error); });
    timer = setTimeout(() => { timedOut = true; stopOwned('TIME_BUDGET_EXCEEDED'); }, options.timeoutMs);
    process.on('SIGINT', onInterrupt); process.on('SIGTERM', onInterrupt);
    child.on('close', (exitCode, signal) => finish(exitCode, signal, true));
  });
}

async function main() {
  const args = argsOf(process.argv.slice(2));
  const repo = fs.realpathSync(args['--repo']), expectedHead = args['--expected-head'], out = canonicalNew(args['--out']);
  outsideGit(out); outsideGit(fs.realpathSync(__filename));
  assert.ok(!inside(repo, out) && !inside(out, repo), 'Evidence and repository must be disjoint');
  fs.mkdirSync(out);
  const runFile = path.join(out, 'run.json');
  const report = {
    schemaVersion: 1, tool: 'ASA repeated full audit wrapper', status: 'RUNNING', acceptedBaseline: false,
    technicalAcceptance: 'PENDING', ownerProductAcceptance: 'PENDING', repo, expectedHead, startedAt: new Date().toISOString(),
    runner: { ...regular(__filename), source: fs.readFileSync(__filename, 'utf8') },
    environment: { node: process.version, executable: process.execPath, platform: process.platform, arch: process.arch, osRelease: os.release() },
    phases: [], artifacts: [], guards: {}, ci: { status: 'NOT_COLLECTED', receipts: [] },
    limitations: [
      'This wrapper never installs, upgrades, fixes dependencies, starts a browser/server, or grants audit acceptance.',
      'STANDARD retains 106 measured samples and 20 warmups; failures are never filtered.',
      'Fresh Node WASM initialization is neither browser cold-start nor OS disk-cache cold; browser cold-start NOT_RUN.',
      'Frozen classifier and archiver contain historical status/limitation strings. Current counts and the actual lifetime receipt are reported separately without rewriting those tools.',
      'Native lifetime regression checks scoped owned handles before cleanup; it is not a whole-vendor native/WASM heap-clean proof.',
      'Exact-head CI and independent review remain separate required evidence; this runner is not the complete acceptance decision.',
    ],
  };
  const flush = () => fs.writeFileSync(runFile, jsonBytes(report));
  let common, archiveApi, toolsDirectory, archiver, checker, npmCli, before, dependenciesBefore, toolBefore, manifestFile, historicalManifest;
  const expectedOutputs = {
    'full-web-types': ['checks/full-web-types.json'], 'standard-performance': ['performance/performance-report.json'],
    'm1-runtime-lifetime': ['checks/native-lifetime.json'], 'npm-audit-capture': ['checks/dependency-audit-input.json'],
    'dependency-classifier': ['checks/dependency-report.json'], 'archive-pack': ['measurement/manifest.json'],
  };
  const recordFile = file => ({ path: path.relative(out, file).replaceAll('\\', '/'), ...Object.fromEntries(Object.entries(regular(file)).filter(([name]) => name !== 'path')) });
  const savePayload = (name, value) => {
    const artifacts = [], descriptor = archiveApi.storePayload(out, name, jsonBytes(value), artifacts);
    report.artifacts.push(...artifacts);
    return descriptor;
  };
  const checkTools = () => {
    assert.equal(hashFile(manifestFile), MANIFEST_SHA);
    assert.equal(hashFile(checker), CHECKER_SHA);
    assert.equal(hashFile(archiver), ARCHIVER_SHA);
    assert.equal(hashFile(__filename), report.runner.sha256);
    const sources = historicalManifest.sources.filter(item => item.id.startsWith('tools/'));
    assert.deepEqual(fileSet(toolsDirectory), sources.map(item => item.id.slice(6)).sort(), 'Frozen external tool inventory changed');
    const files = sources.map(item => {
      const info = regular(path.join(toolsDirectory, item.id.slice(6)));
      assert.equal(info.sha256, item.sha256); assert.equal(info.bytes, item.bytes);
      return { name: item.id.slice(6), bytes: info.bytes, sha256: info.sha256 };
    });
    for (const [name, digest] of Object.entries(TOOLS)) assert.equal(hashFile(path.join(toolsDirectory, name)), digest);
    return files;
  };
  const lightGuard = () => {
    assert.equal(git(repo, 'rev-parse', 'HEAD').trim(), expectedHead, 'HEAD changed');
    assert.equal(git(repo, 'status', '--porcelain=v1', '--untracked-files=all').trim(), '', 'Tracked or untracked source changed');
    assert.deepEqual(ownedDependencies(repo), dependenciesBefore, 'Installed dependency identity/ownership changed');
    assert.deepEqual(checkTools(), toolBefore, 'Frozen tool bytes changed');
  };
  const phase = async (name, command, argv, timeoutMs, validate, extraEnv = {}, acceptedExits = [0]) => {
    lightGuard();
    console.log('START ' + name);
    const meta = { name, startedAt: new Date().toISOString(), command, argv, cwd: repo, executableSha256: hashFile(command), environmentOverrides: { NO_COLOR: '1', TSX_DISABLE_CACHE: '1', npm_config_update_notifier: 'false', ...extraEnv } };
    const childEnv = { ...process.env, ...meta.environmentOverrides };
    const inheritedPath = Object.entries(process.env).find(([name]) => name.toLowerCase() === 'path')?.[1] ?? '';
    for (const name of Object.keys(childEnv)) if (name.toLowerCase() === 'path') delete childEnv[name];
    childEnv.PATH = path.dirname(process.execPath) + path.delimiter + inheritedPath;
    meta.nodeExecutableDirectoryPrependedToPath = path.dirname(process.execPath);
    const result = await execute(command, argv, { cwd: repo, timeoutMs, env: childEnv });
    const receipt = { ...meta, ...result, stdout: encoded(result.stdout), stderr: encoded(result.stderr), status: 'FAIL' };
    try {
      assert.ok(acceptedExits.includes(result.exitCode), 'Unexpected exit code ' + result.exitCode);
      assert.equal(result.signal, null); assert.equal(result.spawnError, null);
      assert.equal(result.timedOut, false); assert.equal(result.outputLimit, false); assert.equal(result.interrupted, false); assert.equal(result.closed, true);
      receipt.validation = validate ? await validate(result) : {};
      receipt.status = 'PASS';
    } catch (error) { receipt.validationError = errorData(error); }
    receipt.outputs = (expectedOutputs[name] ?? []).map(relative => {
      const file = path.join(out, relative);
      if (!fs.existsSync(file)) return { path: relative, status: 'MISSING' };
      try { return { status: 'PRESENT', ...recordFile(file) }; }
      catch (error) { receipt.status = 'FAIL'; return { path: relative, status: 'INVALID', error: errorData(error) }; }
    });
    let guardError;
    try { lightGuard(); receipt.sourceAndToolsUnchanged = true; }
    catch (error) { guardError = error; receipt.sourceAndToolsUnchanged = false; receipt.guardError = errorData(error); receipt.status = 'FAIL'; }
    const descriptor = savePayload('commands/' + String(report.phases.length + 1).padStart(2, '0') + '-' + name + '.json', receipt);
    report.phases.push({ name, status: receipt.status, exitCode: result.exitCode, pid: result.pid, closed: result.closed, timedOut: result.timedOut, outputLimit: result.outputLimit, interrupted: result.interrupted, elapsedMs: result.elapsedMs, receipt: descriptor, outputs: receipt.outputs, validation: receipt.validation ?? null, validationError: receipt.validationError ?? null });
    flush();
    console.log('END ' + name + ' ' + receipt.status);
    if (guardError) throw guardError;
    assert.equal(result.closed, true, 'Owned process cleanup is incomplete; stop further execution');
    assert.equal(result.interrupted, false, 'Wrapper was interrupted; stop further execution');
    return { receipt, result };
  };
  flush();
  try {
    assert.equal(git(repo, 'rev-parse', 'HEAD').trim(), expectedHead);
    assert.equal(git(repo, 'status', '--porcelain=v1', '--untracked-files=all').trim(), '', 'Expected a fresh clean checkout');
    const active = readJson(path.join(repo, 'spec/process/active-work.v1.json'));
    assert.equal(active.currentCheckpoint, 'FULL_REPOSITORY_HEALTH_AUDIT', 'The repeated audit checkpoint must be activated on the accepted base');
    assert.equal(active.productCodeStartAllowed, false); assert.equal(active.auditRepairAllowed, true);
    const packageJson = readJson(path.join(repo, 'package.json'));
    assert.equal(packageJson.scripts['test:m1:runtime'], 'node vendor/toubkal/node_modules/tsx/dist/cli.mjs tests/m1/protected-part-runtime.ts', 'Public M1 entrypoint changed; review the wrapper before execution');
    manifestFile = path.join(repo, HISTORY, 'measurement/manifest.json');
    assert.equal(hashFile(manifestFile), MANIFEST_SHA, 'Historical archive trust binding changed');
    historicalManifest = readJson(manifestFile);
    toolsDirectory = fs.realpathSync(historicalManifest.originals.roots.tools);
    archiver = path.join(fs.realpathSync(historicalManifest.originals.roots.archiver), 'evidence-archiver.mjs');
    checker = path.join(repo, HISTORY, 'full-web-typecheck.cjs');
    outsideGit(toolsDirectory); outsideGit(archiver);
    assert.ok(!inside(toolsDirectory, out) && !inside(out, toolsDirectory) && !inside(path.dirname(archiver), out) && !inside(out, path.dirname(archiver)), 'Output must not overlap frozen tools');
    toolBefore = checkTools();
    dependenciesBefore = ownedDependencies(repo);
    common = await import(pathToFileURL(path.join(toolsDirectory, 'performance-common.mjs')).href);
    archiveApi = await import(pathToFileURL(archiver).href);
    before = common.sourceIdentity(repo, expectedHead);
    report.sourceBefore = savePayload('checks/source-before.json', before);
    report.source = { head: expectedHead, tree: git(repo, 'rev-parse', 'HEAD^{tree}').trim(), fingerprint: before.fingerprint, lock: before.lock, branch: before.branch };
    report.dependenciesBefore = dependenciesBefore;
    report.tools = { historicalManifestSha256: MANIFEST_SHA, directory: toolsDirectory, files: toolBefore, archiver: regular(archiver), checker: regular(checker) };
    npmCli = path.join(path.dirname(process.execPath), 'node_modules/npm/bin/npm-cli.js');
    const npmPackage = readJson(path.join(path.dirname(process.execPath), 'node_modules/npm/package.json'));
    const semver = createRequire(path.join(repo, 'vendor/toubkal/package.json'))('semver');
    for (const pkg of [packageJson, readJson(path.join(repo, 'vendor/toubkal/package.json'))]) {
      if (pkg.engines?.node) assert.ok(semver.satisfies(process.versions.node, pkg.engines.node), 'Node does not satisfy ' + pkg.engines.node);
      if (pkg.engines?.npm) assert.ok(semver.satisfies(npmPackage.version, pkg.engines.npm), 'npm does not satisfy ' + pkg.engines.npm);
    }
    report.environment.npm = npmPackage.version; report.environment.npmCli = regular(npmCli);
    report.environment.nodeExecutable = regular(process.execPath);
    fs.mkdirSync(path.join(out, 'checks'), { recursive: true });
    flush();
    await phase('historical-archive-verify', process.execPath, [archiver, 'verify', '--archive', path.join(repo, HISTORY, 'measurement'), '--manifest-sha', MANIFEST_SHA], 60000);
    const webFile = path.join(out, 'checks/full-web-types.json');
    await phase('full-web-types', process.execPath, [checker, '--repo', repo, '--expected-head', expectedHead, '--out', webFile], 180000, () => {
      const value = readJson(webFile);
      assert.equal(value.head, expectedHead); assert.equal(value.status, 'PASS'); assert.equal(value.errorCount, 0); assert.equal(value.sourceUnchanged, true);
      return { report: recordFile(webFile), rootCount: value.rootCount, errorCount: value.errorCount, typescript: value.typescript };
    });
    const perfDirectory = path.join(out, 'performance'), perfFile = path.join(perfDirectory, 'performance-report.json');
    await phase('standard-performance', process.execPath, [path.join(toolsDirectory, 'performance-runner.mjs'), '--repo', repo, '--expected-head', expectedHead, '--out', perfDirectory], 720000, () => {
      const value = readJson(perfFile), cases = value.phases.flatMap(item => item.worker?.cases ?? []);
      const samples = cases.flatMap(item => item.samples ?? []), warmups = cases.flatMap(item => item.warmups ?? []);
      assert.equal(value.expectedHead, expectedHead); assert.equal(value.status, 'PASS'); assert.equal(value.acceptedBaseline, false);
      assert.equal(value.mode, 'measurement-awaiting-audit-acceptance');
      assert.deepEqual(value.parameters, { samples: 10, warmups: 2, sizes: [8, 32, 128], coldFreshProcessesPerBackend: 3 });
      assert.equal(value.phases.length, 10); assert.equal(cases.length, 16); assert.equal(samples.length, 106); assert.equal(warmups.length, 20);
      assert.ok([...samples, ...warmups].every(item => item.status === 'PASS'));
      assert.ok(Object.values(value.guards).every(item => item === true));
      return { report: recordFile(perfFile), phases: 10, cases: 16, measuredSamples: 106, warmups: 20, acceptedBaseline: false };
    });
    const lifetimeFile = path.join(out, 'checks/native-lifetime.json');
    await phase('m1-runtime-lifetime', process.execPath, [npmCli, 'run', 'test:m1:runtime'], 240000, () => {
      const value = readJson(lifetimeFile);
      assert.equal(value.cases.length, 14); assert.equal(value.passed, 14); assert.equal(value.failed, 0);
      assert.ok(value.cases.every(item => item.passed && item.error === null && item.observation.totalCreated > 0 && item.observation.totalLive === 0));
      return { report: recordFile(lifetimeFile), passed: value.passed, failed: value.failed, observedCreated: value.cases.reduce((sum, item) => sum + item.observation.totalCreated, 0), observedLiveBeforeCleanup: value.cases.reduce((sum, item) => sum + item.observation.totalLive, 0), scope: value.scope };
    }, { ASA_STABLEREF_LIFETIME_REPORT: lifetimeFile, npm_config_cache: path.join(out, 'npm-cache') });
    const auditFile = path.join(out, 'checks/dependency-audit-input.json');
    let auditReady = false;
    await phase('npm-audit-capture', process.execPath, [npmCli, '--prefix', path.join(repo, 'vendor/toubkal'), 'audit', '--json', '--registry=https://registry.npmjs.org'], 180000, result => {
      const value = JSON.parse(result.stdout.toString('utf8'));
      assert.equal(value.auditReportVersion, 2); assert.equal(value.error, undefined);
      assert.ok(value.vulnerabilities && typeof value.vulnerabilities === 'object' && !Array.isArray(value.vulnerabilities));
      const counts = value.metadata?.vulnerabilities;
      assert.ok(counts && Number.isInteger(counts.total) && counts.total >= 0);
      assert.ok(['info', 'low', 'moderate', 'high', 'critical'].every(name => Number.isInteger(counts[name]) && counts[name] >= 0));
      assert.equal(['info', 'low', 'moderate', 'high', 'critical'].reduce((sum, name) => sum + counts[name], 0), counts.total);
      assert.equal(Object.keys(value.vulnerabilities).length, counts.total);
      assert.equal(result.exitCode, counts.total > 0 ? 1 : 0, 'npm exit does not match vulnerability metadata');
      fs.writeFileSync(auditFile, result.stdout, { flag: 'wx' }); auditReady = true;
      report.currentDependencyFindings = { npmExitCode: result.exitCode, counts, capturedAt: new Date().toISOString(), input: recordFile(auditFile), network: 'Fresh npm audit against explicitly named registry; no audit fix or install' };
      return report.currentDependencyFindings;
    }, { npm_config_cache: path.join(out, 'npm-cache') }, [0, 1]);
    const dependencyFile = path.join(out, 'checks/dependency-report.json');
    let dependencyReady = false;
    if (auditReady) await phase('dependency-classifier', process.execPath, [path.join(toolsDirectory, 'dependency-classifier.mjs'), '--repo', repo, '--expected-head', expectedHead, '--audit', auditFile, '--out', dependencyFile], 120000, () => {
      const value = readJson(dependencyFile);
      assert.equal(value.sourceHead, expectedHead); assert.equal(value.checkoutCleanBeforeAndAfter, true);
      assert.equal(value.sourceFingerprintBefore, before.fingerprint); assert.equal(value.sourceFingerprintAfter, before.fingerprint);
      assert.equal(value.lock.sha256, before.lock.sha256); assert.equal(value.capturedAudit.sha256, hashFile(auditFile));
      dependencyReady = true;
      return { report: recordFile(dependencyFile), rawStatus: value.status, counts: value.counts, sourceFiles: value.mainProductImportGraph.sourceFileCount, unresolvedLiteralImports: value.mainProductImportGraph.unresolvedLiteralImports.length };
    });
    else report.blocked = [...(report.blocked ?? []), 'dependency-classifier: no authentic complete npm audit input'];
    if (dependencyReady && fs.existsSync(perfFile) && ['PASS', 'FAIL'].includes(readJson(perfFile).status) && readJson(perfFile).endedAt) {
      const archiveDirectory = path.join(out, 'measurement'), restoredDirectory = path.join(out, 'roundtrip');
      const packed = await phase('archive-pack', process.execPath, [archiver, 'pack', '--performance', perfDirectory, '--dependency', dependencyFile, '--audit', auditFile, '--tools', toolsDirectory, '--expected-head', expectedHead, '--out', archiveDirectory], 120000);
      if (packed.receipt.status === 'PASS') {
        const manifest = path.join(archiveDirectory, 'manifest.json'), digest = hashFile(manifest), value = readJson(manifest);
        report.measurementArchive = { directory: 'measurement', manifest: recordFile(manifest), manifestSha256: digest, sourceOutcome: value.sourceOutcome, eligibility: value.archiveEligibility };
        const verified = await phase('archive-verify', process.execPath, [archiver, 'verify', '--archive', archiveDirectory, '--manifest-sha', digest], 120000);
        if (verified.receipt.status === 'PASS') await phase('archive-roundtrip', process.execPath, [archiver, 'unpack', '--archive', archiveDirectory, '--manifest-sha', digest, '--out', restoredDirectory], 120000, () => {
          const roots = { performance: perfDirectory, tools: toolsDirectory, dependency: path.dirname(dependencyFile), audit: path.dirname(auditFile), archiver: path.dirname(archiver) };
          for (const source of value.sources) {
            const [root, ...parts] = source.id.split('/');
            assert.ok(Object.hasOwn(roots, root) && parts.length && parts.every(part => part && part !== '.' && part !== '..'));
            const original = fs.readFileSync(path.join(roots[root], ...parts)), restored = fs.readFileSync(path.join(restoredDirectory, source.id));
            assert.equal(original.length, source.bytes); assert.equal(hash(original), source.sha256);
            assert.ok(original.equals(restored), 'Roundtrip differs from the actual original bytes: ' + source.id);
          }
          assert.deepEqual(fileSet(restoredDirectory), value.sources.map(item => item.id).sort());
          assert.equal(hashFile(manifest), digest);
          return { manifestSha256: digest, originalFiles: value.sources.length, originalBytes: value.originals.totalBytes, allOriginalBytesEqual: true, archiveFiles: value.artifacts.length + 1, largestArchiveFileBytes: Math.max(fs.statSync(manifest).size, ...value.artifacts.map(item => item.bytes)), rawCounts: value.rawCounts };
        });
      }
    } else report.blocked = [...(report.blocked ?? []), 'archive: completed performance and matching dependency inputs are required'];
  } catch (error) { report.executionError = errorData(error); }
  finally {
    if (before && common) {
      try {
        lightGuard();
        const after = common.sourceIdentity(repo, expectedHead);
        report.sourceAfter = savePayload('checks/source-after.json', after);
        report.guards.sourceUnchanged = after.fingerprint === before.fingerprint;
        report.guards.checkoutClean = after.checkoutClean;
        report.guards.nodeAndNpmUnchanged = hashFile(process.execPath) === report.environment.nodeExecutable.sha256 && hashFile(npmCli) === report.environment.npmCli.sha256;
        report.guards.toolsUnchanged = JSON.stringify(checkTools()) === JSON.stringify(toolBefore);
        report.guards.physicalOwnedDependenciesUnchanged = JSON.stringify(ownedDependencies(repo)) === JSON.stringify(dependenciesBefore);
      } catch (error) { report.postflightError = errorData(error); }
    }
    report.guards.noBrowserOrServerStarted = true;
    report.guards.allInvokedCommandsClosed = report.phases.length > 0 && report.phases.every(item => item.closed === true && item.pid !== null);
    report.guards.noTimeoutOrInterruption = report.phases.every(item => !item.timedOut && !item.outputLimit && !item.interrupted);
    const required = ['historical-archive-verify', 'full-web-types', 'standard-performance', 'm1-runtime-lifetime', 'npm-audit-capture', 'dependency-classifier', 'archive-pack', 'archive-verify', 'archive-roundtrip'];
    report.guards.everyRequiredPhasePassed = required.every(name => report.phases.some(item => item.name === name && item.status === 'PASS'));
    report.guards.noCurrentDependencyFindings = report.currentDependencyFindings?.counts?.total === 0;
    report.guards.archiveEligible = report.measurementArchive?.eligibility?.status === 'IDENTITY_CHECKS_PASS_ACCEPTANCE_NOT_GRANTED';
    report.status = !report.executionError && !report.postflightError && !report.blocked?.length && Object.values(report.guards).every(value => value === true) ? 'PASS' : 'FAIL';
    report.endedAt = new Date().toISOString();
    flush();
  }
  console.log(JSON.stringify({ status: report.status, acceptedBaseline: false, technicalAcceptance: 'PENDING', expectedHead, report: runFile, reportSha256: hashFile(runFile), phases: report.phases.map(({ name, status, exitCode }) => ({ name, status, exitCode })), guards: report.guards }, null, 2));
  process.exitCode = report.status === 'PASS' ? 0 : 1;
}
main().catch(error => { console.error(error.stack ?? error); process.exitCode = 1; });
